import { execFile } from "node:child_process";
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

/** The most steps `pipe` and `flow` take, as their overloads in `index.ts` declare. */
const steps = 20;

const root = new URL("../../../../", import.meta.url);
const header =
  "// Generated by generate-tests.ts. Run `node scripts/bundle-size/util/pipe/generate-tests.ts` to update.";

function nested(depth: number): string {
  return `number${"[]".repeat(depth)}`;
}

// The type error lands on the first step past the last overload, so the directive goes there.
function tooMany(call: string): string {
  return [
    `    ${call}(`,
    "      0,",
    ...Array<string>(steps).fill("      wrap,"),
    "      // @ts-expect-error no overload takes this many steps",
    "      wrap,",
    "    );",
  ].join("\n");
}

const lengths = Array.from({ length: steps }, (_, i) => i + 1);

// Every step changes the type, so an overload that wires a step to the wrong one fails. The last
// step of each `flow` call is async, so an overload whose result skips `Awaited` fails too.
const tests = `${header}
import { describe, expectTypeOf, test } from "vite-plus/test";

import { flow, pipe } from "./index.ts";

const wrap = <T>(x: T): T[] => [x];
const wrapAsync = async <T>(x: T): Promise<T[]> => [x];

describe("pipe", () => {
  test("chains each step to the one before, at every length", () => {
${lengths
  .map(
    (n) =>
      `    expectTypeOf(pipe(0, ${Array(n).fill("wrap").join(", ")})).toEqualTypeOf<${nested(n)}>();`,
  )
  .join("\n")}
${tooMany("pipe")}
  });
});

describe("flow", () => {
  test("chains each step to the resolved one before, at every length", () => {
${lengths
  .map((n) => {
    const chain = lengths
      .slice(0, n)
      .map((i) => ((n - i) % 2 === 0 ? "wrapAsync" : "wrap"))
      .join(", ");
    return `    expectTypeOf(flow(0, ${chain})).toEqualTypeOf<Promise<${nested(n)}>>();`;
  })
  .join("\n")}
${tooMany("void flow")}
  });
});
`;

function format(file: URL, text: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = execFile(
      fileURLToPath(new URL("node_modules/.bin/vp", root)),
      ["fmt", `--stdin-filepath=${fileURLToPath(file)}`],
      { cwd: fileURLToPath(root) },
      (error, stdout) => (error ? reject(error) : resolve(stdout)),
    );
    child.stdin?.end(text);
  });
}

/** Where {@link generate} writes. */
const output = new URL("generated.test.ts", import.meta.url);

/** The type tests, one per overload, formatted. */
export function generate(): Promise<string> {
  return format(output, tests);
}

if (import.meta.main) {
  await writeFile(output, await generate());
}
